// static
bool UnionTraits<::ipp_parser::mojom::IppAttributeValue::DataView, ::ipp_parser::mojom::IppAttributeValuePtr>::Read(
    ::ipp_parser::mojom::IppAttributeValue::DataView input,
    ::ipp_parser::mojom::IppAttributeValuePtr* output) {
  using UnionType = ::ipp_parser::mojom::IppAttributeValue;
  using Tag = UnionType::Tag;

  switch (input.tag()) {
    case Tag::kBools: {
      std::vector<bool> result_bools;
      if (!input.ReadBools(&result_bools))
        return false;

      *output = UnionType::NewBools(
          std::move(result_bools));
      break;
    }
    case Tag::kDate: {
      std::vector<uint8_t> result_date;
      if (!input.ReadDate(&result_date))
        return false;

      *output = UnionType::NewDate(
          std::move(result_date));
      break;
    }
    case Tag::kInts: {
      std::vector<int32_t> result_ints;
      if (!input.ReadInts(&result_ints))
        return false;

      *output = UnionType::NewInts(
          std::move(result_ints));
      break;
    }
    case Tag::kStrings: {
      std::vector<std::string> result_strings;
      if (!input.ReadStrings(&result_strings))
        return false;

      *output = UnionType::NewStrings(
          std::move(result_strings));
      break;
    }
    case Tag::kOctets: {
      std::vector<std::vector<uint8_t>> result_octets;
      if (!input.ReadOctets(&result_octets))
        return false;

      *output = UnionType::NewOctets(
          std::move(result_octets));
      break;
    }
    case Tag::kResolutions: {
      std::vector<::ipp_parser::mojom::ResolutionPtr> result_resolutions;
      if (!input.ReadResolutions(&result_resolutions))
        return false;

      *output = UnionType::NewResolutions(
          std::move(result_resolutions));
      break;
    }
    default:

      return false;
  }
  return true;
}

