void IppParserInterceptorForTesting::ParseIpp(const std::vector<uint8_t>& to_parse, ParseIppCallback callback) {
  GetForwardingInterface()->ParseIpp(std::move(to_parse), std::move(callback));
}
IppParserAsyncWaiter::IppParserAsyncWaiter(
    IppParser* proxy) : proxy_(proxy) {}

IppParserAsyncWaiter::~IppParserAsyncWaiter() = default;

void IppParserAsyncWaiter::ParseIpp(
    const std::vector<uint8_t>& to_parse, IppRequestPtr* out_request) {
  base::RunLoop loop;
  proxy_->ParseIpp(std::move(to_parse),
      base::BindOnce(
          [](base::RunLoop* loop,
             IppRequestPtr* out_request
,
             IppRequestPtr request) {*out_request = std::move(request);
            loop->Quit();
          },
          &loop,
          out_request));
  loop.Run();
}

IppRequestPtr IppParserAsyncWaiter::ParseIpp(
    const std::vector<uint8_t>& to_parse) {
  IppRequestPtr async_wait_result;
  ParseIpp(std::move(to_parse),&async_wait_result);
  return async_wait_result;
}






